"""Writes GorillaAkimboLowered.archive.xl: the lowered (safe) stance sets of lowsets.py on the player entities.
usage: genlowxl.py <out .archive.xl> <lowclips dir>
Guns and poses come from weapons.json."""
import os, sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from lowsets import plan

import manifest

SEP = chr(92)  # backslash
ENTITIES = {body: manifest.entities(body) for body in manifest.bodies()}
lines = ['# Gorilla Akimbo: lowered (safe) stance for dual-wielded SMGs and shotguns, per hand.',
         '# Generated by genlowxl.py.', 'animations:']
for body, side, name, _, entries in plan(sys.argv[2]):
    for vars_, priority in entries:
        lines.append('  - entity: [' + ', '.join(ENTITIES[body]) + ']')
        lines.append('    set: ' + SEP.join(['gorillaakimbo', 'animations', name + '.anims']))
        lines.append('    vars: [' + ', '.join(vars_) + ']')
        lines.append(f'    priority: {priority}')
open(sys.argv[1], 'w', newline='\n').write('\n'.join(lines) + '\n')
print(sum(1 for l in lines if l.startswith('  - ')), 'entries')
